Create Sample From Lab Order.code:
// Create a sample (AnalysisRequest) inside a client, e.g. from an OpenMRS lab order.
// baseUrl is the SENAITE site root; JSON API paths start with @@API/senaite/v1.
request(
  // 1) HTTP method.
  'POST',
  // 2) Create an AnalysisRequest in the client folder with this UID.
  '@@API/senaite/v1/AnalysisRequest/create/c1000000000000000000000000000001', // e.g. $.data.clientUid
  // 3) Options: the sample fields go in the body.
  {
    body: {
      Contact: $.data.contactUid,
      SampleType: $.data.sampleTypeUid,
      DateSampled: $.data.collectedAt,
      ClientSampleID: $.data.orderNumber,
      // UIDs of the AnalysisServices to run.
      Analyses: ['5e000000000000000000000000000001'], // e.g. $.data.testUids
    },
  }
);

Create Client.code:
// Create a Client (e.g. a referring health facility).
request('POST', '@@API/senaite/v1/Client/create', {
  body: {
    title: $.data.facilityName,
    ClientID: $.data.facilityCode,
    parent_path: '/senaite/clients',
  },
});

Receive Sample.code:
// Update a sample and run a workflow transition on it.
request('POST', '@@API/senaite/v1/AnalysisRequest/update/a5000000000000000000000000000001', { // e.g. $.data.sampleUid
  body: {
    // Workflow transition to run after the update.
    transition: 'receive',
    Remarks: 'Received via courier from district hospital',
  },
});

Update Object By UID.code:
// Update fields on any object (portal type inferred from the UID).
request('POST', '@@API/senaite/v1/update/c1000000000000000000000000000001', { // e.g. $.data.uid
  body: {
    Phone: $.data.phone,
    EmailAddress: $.data.email,
  },
});

Create Sample Partitions.code:
// Split a received sample into two partitions (senaite.jsonapi 2.7.0+).
// The listed analyses move from the primary sample into the partition.
request('POST', '@@API/senaite/v1/partition', {
  body: {
    uid: 'a5000000000000000000000000000001', // e.g. $.data.sampleUid
    partitions: [
      { analyses: [] }, // e.g. $.data.analysisUids
      { analyses: [], internal_use: true },
    ],
  },
});

Get Published Results.code:
// Find samples published recently, returning full object data.
request('GET', '@@API/senaite/v1/search', {
  query: {
    portal_type: 'AnalysisRequest',
    catalog: 'senaite_catalog_sample',
    review_state: 'published',
    modified_since: '2d',
    complete: 'yes',
    limit: 100,
  },
});

Find Sample By Client Sample ID.code:
// Find a sample by the client's own sample/order id.
request('GET', '@@API/senaite/v1/AnalysisRequest', {
  query: {
    getClientSampleID: $.data.orderNumber,
    catalog: 'senaite_catalog_sample',
    complete: 'yes',
  },
});

List Analysis Services.code:
// List active analysis services.
request('GET', '@@API/senaite/v1/AnalysisService', {
  query: { review_state: 'active', complete: 'yes', limit: 200 },
});

Get Required Sample Fields.code:
// Which fields does a sample need? (senaite.jsonapi 2.7.0+)
// Each field has name, type, required, readonly and, for references, allowed_types.
request('GET', '@@API/senaite/v1/schema/AnalysisRequest');
fn(state => {
  state.required = state.data.fields.filter(f => f.required).map(f => f.name);
  return state;
});

